const zone = 'America/Toronto';
const now = DateTime.now().setZone(zone);
const start = now.minus({ days: 7 });
const clean = (v) => (v === undefined || v === null ? '' : String(v).trim());
const parse = (v) => {
  const s = clean(v);
  if (!s) return null;
  let d = DateTime.fromFormat(s, 'yyyy-MM-dd HH:mm', { zone });
  if (!d.isValid) d = DateTime.fromISO(s, { zone });
  return d.isValid ? d.setZone(zone) : null;
};
const memory = $('Read Memory Tab').all().map(i => i.json).filter(r => r && clean(r.id) && clean(r.note));
const actions = $('Read Actions Tab').all().map(i => i.json).filter(r => r && clean(r.id));

const doneLog = memory.filter(r => clean(r.type).toLowerCase() === 'done');
const active = memory
  .filter(r => clean(r.type).toLowerCase() !== 'done')
  .filter(r => !['done', 'archived'].includes(clean(r.status).toLowerCase()))
  .map(r => ({ ...r, _at: parse(r.captured_at) }))
  .filter(r => r._at && r._at >= start && r._at <= now)
  .sort((a, b) => a._at.toMillis() - b._at.toMillis());

const rows = active.map(r => ({
  id: clean(r.id), row: clean(r.row_number), captured: r._at.toFormat('ccc LLL d'),
  person_or_project: clean(r.person_or_project), due_date: clean(r.due_date), note: clean(r.note)
}));

const notesText = active.map(r => [
  `ROW ${clean(r.row_number) || '?'} | id: ${clean(r.id)}`,
  `  captured: ${r._at.toFormat('ccc yyyy-MM-dd HH:mm')}`,
  `  status: ${clean(r.status) || 'new'}`,
  `  person_or_project: ${clean(r.person_or_project) || '(blank)'}`,
  `  due_date: ${clean(r.due_date) || '(blank)'}`,
  `  note: ${clean(r.note)}`
].join('\n')).join('\n\n');

const completedText = doneLog.map(r => `- ${clean(r.note)} (logged ${clean(r.captured_at)}, ${clean(r.id)})`).join('\n');

const openActions = actions.filter(a => !['rejected'].includes(clean(a.approval_status).toLowerCase()));
const actionsText = openActions.map(a => `- ${clean(a.id)} [${clean(a.approval_status) || 'pending'}${clean(a.outcome).startsWith('http') ? ', draft exists' : ''}]: ${clean(a.proposed_action)}`).join('\n');

const nums = actions.map(a => parseInt(clean(a.id).replace(/^A-/i, ''), 10)).filter(n => !isNaN(n));
const nextActionNum = (nums.length ? Math.max(...nums) : 0) + 1;

// ---------- Gmail ----------
const flat = (v) => clean(v).replace(/[{}]/g, ' ').replace(/\s+/g, ' ').trim();
const emailItems = $('Read Important Emails').all().map(i => i.json);
const email_error = emailItems.some(e => e && e.error);
const seenThreads = new Set();
const seenSubjects = new Set();
const emails = emailItems
  .filter(e => e && e.id && !e.error)
  .sort((a, b) => Number(b.internalDate || 0) - Number(a.internalDate || 0))
  .filter(e => {
    const thread = clean(e.threadId || e.id);
    const subject = `${flat(e.From)}|${flat(e.Subject).replace(/^(re|fwd?):\s*/i, '').toLowerCase()}`;
    if (seenThreads.has(thread) || seenSubjects.has(subject)) return false;
    seenThreads.add(thread);
    seenSubjects.add(subject);
    return true;
  })
  .map((e, i) => {
    const from = flat(e.From);
    const at = e.internalDate ? DateTime.fromMillis(Number(e.internalDate)).setZone(zone) : null;
    return {
      ref: `E${i + 1}`,
      from,
      from_name: flat(from.replace(/<[^>]*>/g, '').replace(/"/g, '')) || from,
      subject: flat(e.Subject) || '(no subject)',
      snippet: flat(e.snippet).slice(0, 220),
      received: at && at.isValid ? at.toFormat('ccc LLL d') : '',
      unread: (e.labels || []).some(l => l && l.id === 'UNREAD'),
      url: `https://mail.google.com/mail/?authuser=YOUR@EMAIL.COM#all/${clean(e.threadId || e.id)}`
    };
  });
const emailsText = emails.map(e => `${e.ref} | ${e.unread ? 'UNREAD' : 'read'} | ${e.received} | from: ${e.from} | subject: ${e.subject} | preview: ${e.snippet}`).join('\n');

// ---------- Calendar ----------
const calItems = $('Read Calendar').all().map(i => i.json);
const calendar_error = calItems.some(e => e && e.error);
const seen = new Set();
const todayStart = now.startOf('day');
const shorten = (t) => t.length > 90 ? t.slice(0, 87).trimEnd() + '...' : t;
const events = calItems
  .filter(e => e && e.start && !e.error && e.status !== 'cancelled')
  .filter(e => !(e.attendees || []).some(a => a.self && a.responseStatus === 'declined'))
  .filter(e => {
    const key = `${e.iCalUID || e.id}|${e.start.dateTime || e.start.date}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .map(e => {
    const allDay = !e.start.dateTime;
    let s = allDay ? DateTime.fromISO(e.start.date, { zone }) : DateTime.fromISO(e.start.dateTime).setZone(zone);
    const f = e.end && e.end.dateTime ? DateTime.fromISO(e.end.dateTime).setZone(zone) : null;
    if (s < todayStart) s = todayStart;
    return {
      millis: allDay ? s.startOf('day').toMillis() : s.toMillis(),
      day: s.toFormat('cccc, LLL d'),
      time: allDay ? 'All day' : `${s.toFormat('h:mm a')}${f ? ' - ' + f.toFormat('h:mm a') : ''}`,
      title: shorten(clean(e.summary) || '(no title)'),
      location: clean(e.location),
      url: clean(e.htmlLink).startsWith('https://') ? clean(e.htmlLink) : ''
    };
  })
  .sort((a, b) => a.millis - b.millis);

return [{ json: {
  count: active.length,
  rows,
  actions: actions.map(a => ({ id: clean(a.id), status: clean(a.approval_status).toLowerCase() || 'pending', text: clean(a.proposed_action), outcome: clean(a.outcome) })),
  next_action_num: nextActionNum,
  window_start: start.toFormat('ccc LLL d, HH:mm'),
  window_end: now.toFormat('ccc LLL d, HH:mm'),
  today: now.toFormat('cccc yyyy-MM-dd'),
  digest_date: now.toFormat('cccc, LLLL d'),
  short_date: now.toFormat('ccc LLL d, yyyy'),
  notes_text: notesText || '(none)',
  completed_text: completedText || '(none)',
  actions_text: actionsText || '(none)',
  emails,
  emails_text: emailsText || '(none)',
  email_error,
  events,
  calendar_error
} }];

